/// Marks already painted in their colour, keyed by name and ink.
///
/// Every icon used to be drawn through a colour filter, and a colour filter is a
/// layer: a screen carrying two dozen marks paid for two dozen of them every
/// frame. The drawings carry `currentColor`, so the colour can be written into
/// the document instead, and each finished document is built once and kept.
final _painted = <String, String>{};

/// One mark, in the colour and size it is asked for.
class CalviIcon extends StatelessWidget {
  const CalviIcon(this.name, {super.key, this.size = 22, this.color});

  final String name;
  final double size;
  final Color? color;

  @override
  Widget build(BuildContext context) {
    /* A name the set does not have draws the plate rather than nothing: the
       registry is shared with the server, and a key added there before the mark
       is drawn here must not leave a hole in the day. */
    assert(calviIcons.containsKey(name), 'no icon named "$name"');
    final art = calviIcons[name] ?? calviIcons['plate']!;

    /* The ink of the page, not the colour of the text around it. Material's
       default text style is bodyMedium, which in this theme is the secondary
       grey, so every mark that did not name a colour came out washed out against
       the demo. A mark that is meant to be quiet asks for it. */
    final tint = color ?? context.c.text;
    final rgb = tint.toARGB32() & 0xFFFFFF;
    final doc = _painted['$name#$rgb'] ??= art.replaceAll(
      'currentColor',
      '#${rgb.toRadixString(16).padLeft(6, '0')}',
    );

    return SvgPicture.string(
      doc,
      width: size,
      height: size,
      /* Only a mark asked for at less than full strength still needs a filter,
         and those are rare enough to pay for a layer. */
      colorFilter: tint.a < 1 ? ColorFilter.mode(tint, BlendMode.srcIn) : null,
    );
  }
}
